for call in (lambda: int('abc'), lambda: [1].index(9)):
    try:
        call()
    except ValueError as exc:
        print(type(exc).__name__, '-', exc)

def set_qty(n):
    if n < 0:
        raise ValueError(f'qty must be >= 0, got {n}')
    return n

try:
    set_qty(-1)
except ValueError as exc:
    print(exc)
